SELECT r.ACCOUNTS_RECEIVABLE_AND_PAYABLE_ID AS accountsReceivableAndPayableId, r.company_id AS companyId, c.company_abbreviation AS companyAbbreviation, r.closing_date AS closingDate, r.line_total AS lineTotal, r.amount_charged AS amountCharged, r.deposit_amount AS depositAmount, r.commission AS commission, r.expected_date_of_payment AS expectedDateOfPayment, r.deposit_date AS depositDate FROM basic_v2_accounts_receivable_and_payable r LEFT JOIN basic_v2_company_management c ON r.company_id = c.company_id WHERE r.BUY_AND_SELL_TYPE = 2 AND c.sale_or_procurement = 2 AND r.active_flg = 1 AND c.active_flg = 1
AND r.expected_date_of_payment >= #{expectedStart}
AND r.expected_date_of_payment <= #{expectedEnd}
AND STR_TO_DATE(r.closing_date, '%Y-%m-%d') >= #{closingStart}
AND STR_TO_DATE(r.closing_date, '%Y-%m-%d') <= #{closingEnd}

SELECT r.ACCOUNTS_RECEIVABLE_AND_PAYABLE_ID AS accountsReceivableAndPayableId, r.company_id AS companyId, c.company_abbreviation AS companyAbbreviation, r.closing_date AS closingDate, r.line_total AS lineTotal, r.TARGET_YEAR_AND_MONTH AS targetYearAndMonth, r.amount_charged AS amountCharged, r.deposit_amount AS depositAmount, r.commission AS commission, r.expected_date_of_payment AS expectedDateOfPayment, r.deposit_date AS depositDate FROM basic_v2_accounts_receivable_and_payable r LEFT JOIN basic_v2_company_management c ON r.company_id = c.company_id WHERE r.BUY_AND_SELL_TYPE = 1 AND c.sale_or_procurement = 1 AND r.active_flg = 1 AND c.active_flg = 1
AND r.expected_date_of_payment >= #{expectedStart}
AND r.expected_date_of_payment <= #{expectedEnd}
AND STR_TO_DATE(r.closing_date, '%Y-%m-%d') >= #{closingStart}
AND STR_TO_DATE(r.closing_date, '%Y-%m-%d') <= #{closingEnd}
